// ==UserScript==
// @name             KrunkerHVH Loader (Quirify stack, keyless)
// @namespace        https://github.com/titus/krunkerhvh
// @version          3.5
// @description      Krunker.io Cheats by Quirify's Tools
// @author           Quirify
// @match            *://krunker.io/*
// @match            *://*.browserfps.com/*
// @exclude          *://krunker.io/social*
// @exclude          *://krunker.io/editor*
// @exclude          *://krunker.io/viewer*
// @icon             https://quirify.dev/images/logo.gif
// @grant            none
// @run-at           document-start
// @noframes
// ==/UserScript==

(function () {
  'use strict';
  var Q = /quirify/i;
  // Broader auth-request detector: match license/auth-like URLs or bodies, but NEVER
  // intercept game code / third-party assets (the cheat loads game.js from GitHub/Vercel,
  // which would otherwise be wrongly faked and crash the cheat).
  function isAuth(u, body) {
    u = u || '';
    if (/githubusercontent|github\.com|Krunker-Server-data|game\.js|game_3_0|cookiepro|cookie|google\.com|krunker\.io|analytics/i.test(u)) return false;
    if (/matchmaker\.krunker\.io|challenges\.cloudflare\.com|altcha|captcha|turnstile/i.test(u)) return false;
    if (/quirify\.dev/i.test(u)) return true;            // the real license API host
    if (/twitchfollows\.de/i.test(u)) return true;       // cheat's auth/feature server
    if (Q.test(u)) return true;                          // any other quirify* host
    var hay = u + ' ' + (body || '');
    if (/matchmaker\.krunker\.io|challenges\.cloudflare\.com|altcha|captcha|turnstile|generate-token|validationtoken/i.test(hay)) return false;
    return /licen[sc]e|validate|valid|token|auth|activate|hwid|session|\bkey\b|register|unlock/i.test(hay);
  }

  // ---------- debug menu ----------
  var DEBUG = true;
  var panel = null, hidden = false, buffer = [];
  function ensurePanel() {
    if (panel) return panel;
    var root = document.body || document.documentElement;
    if (!root) return null;
    panel = document.createElement('div');
    panel.id = 'quirify-unlocker-debug';
    panel.style.cssText = 'position:fixed;top:8px;left:8px;z-index:2147483647;max-width:420px;max-height:65vh;overflow:auto;background:rgba(0,0,0,.86);color:#39ff14;font:11px/1.4 monospace;padding:8px 10px;border:1px solid #39ff14;white-space:pre-wrap;box-shadow:0 0 8px #000;';
    root.appendChild(panel);
    if (buffer.length) { panel.textContent = buffer.join('\n') + '\n'; buffer = []; }
    return panel;
  }
  function dbg(msg) {
    try { console.log('[Quirify Unlocker] ' + msg); } catch (e) {}
    if (!DEBUG) return;
    var p = ensurePanel();
    if (p) p.textContent += msg + '\n'; else buffer.push(msg);
  }
  function dump(label, obj) {
    try { dbg(label + ': ' + JSON.stringify(obj)); } catch (e) { dbg(label + ': ' + String(obj)); }
  }
  // toggle with backtick (`) or F8
  window.addEventListener('keydown', function (e) {
    if (e.key === '`' || e.key === 'F8') { hidden = !hidden; if (panel) panel.style.display = hidden ? 'none' : 'block'; }
  });
  window.addEventListener('error', function (e) { dbg('PAGE ERROR: ' + (e && e.message) + (e && e.filename ? ' @' + e.filename + ':' + e.lineno : '')); });
  window.addEventListener('unhandledrejection', function (e) { dbg('PROMISE REJECT: ' + (e && e.reason && (e.reason.message || e.reason))); });
  dbg('debug menu ready (press ` or F8 to hide)');

  // Build a fake "valid" response that *echoes back* whatever the cheat posted,
  // so both `if (res.valid)` truthy checks AND `res.licenseKey === submittedKey`
  // equality checks pass. Unknown fields are truthy via the Proxy.
  function makeResp(bodyObj) {
    var data = Object.assign({}, bodyObj || {}, {
      valid: true, active: true, success: true, status: 'active', licensed: true
    });
    var json = new Proxy(data, { get: function (t, p) { return (p in t) ? t[p] : true; } });
    return new Proxy({ status: 200, ok: true, statusText: 'OK' }, {
      get: function (t, p) {
        if (p === 'json') return function () { return Promise.resolve(json); };
        if (p === 'text') return function () { return Promise.resolve(JSON.stringify(data)); };
        if (p === 'clone') return function () { return makeResp(bodyObj); };
        if (p in t) return t[p];
        return true;
      }
    });
  }

  // --- fetch interception: emulate the keyauth endpoint ---
  var realFetch = (typeof window !== 'undefined' && window.fetch) ? window.fetch.bind(window) : null;
  dbg('window.fetch present: ' + (!!realFetch));
  if (realFetch) {
    window.fetch = function (url, opts) {
      var u = (url && typeof url === 'object' && url.url) ? url.url : ('' + (url || ''));
      var hit = isAuth(u, opts && opts.body);
      dbg((hit ? '>>> FETCH intercepted: ' : '    fetch: ') + u);
      if (hit) {
        dump('    body', opts && opts.body);
        var body = {};
        try { if (opts && opts.body) body = JSON.parse(opts.body); } catch (e) {}
        return Promise.resolve(makeResp(body));
      }
      return realFetch(url, opts);
    };
  } else {
    dbg('!! window.fetch NOT available — cannot intercept fetch');
  }

  // --- XMLHttpRequest interception (antitamper / heartbeat) ---
  // IMPORTANT: must be a real `class extends` so the cheat's own `class extends
  // XMLHttpRequest` patches keep working (a plain function returning a new XHR would
  // discard the subclass instance and break the game's asset loading).
  var RealXHR = (typeof window !== 'undefined' && window.XMLHttpRequest) ? window.XMLHttpRequest : null;
  dbg('window.XMLHttpRequest present: ' + (!!RealXHR));
  if (RealXHR && RealXHR.prototype) {
    window.XMLHttpRequest = class extends RealXHR {
      open() {
        this.__u = ('' + (arguments[1] || ''));
        return super.open.apply(this, arguments);
      }
      send() {
        var hit = isAuth(this.__u || '', arguments[0]);
        dbg((hit ? '>>> XHR intercepted: ' : '    xhr: ') + this.__u);
        if (hit) {
          dump('    body', arguments[0]);
          var b = {};
          try { if (arguments[0]) b = JSON.parse(arguments[0]); } catch (e) {}
          var data = Object.assign({}, b, { valid: true, active: true, success: true });
          try {
            this.status = 200; this.statusText = 'OK';
            this.responseText = JSON.stringify(data); this.response = this.responseText; this.readyState = 4;
            if (this.onreadystatechange) this.onreadystatechange();
            if (this.onload) this.onload();
          } catch (e) {}
          return;
        }
        return super.send.apply(this, arguments);
      }
    };
  } else {
    dbg('!! window.XMLHttpRequest NOT available');
  }

  // --- seed the license key so the loader believes one is present ---
  if (typeof window !== 'undefined' && window.Storage && window.Storage.prototype && window.Storage.prototype.getItem) {
    var _get = window.Storage.prototype.getItem;
    window.Storage.prototype.getItem = function (k) {
      var v = _get.call(this, k);
      if (v == null && typeof k === 'string' && /quirify|licen[sc]e/i.test(k)) {
        dbg('SEED localStorage["' + k + '"] -> "quirify-keyless"');
        return 'quirify-keyless';
      }
      return v;
    };
    dbg('localStorage.getItem override installed');
  } else {
    dbg('!! Storage.prototype.getItem unavailable — cannot seed key');
  }

  // --- NOTE: we intentionally do NOT override location.reload / alert. Blocking reload
  // can stall the game's own legitimate reloads, and the brick path only fires on an
  // *invalid* key (which our emulation prevents), so it never triggers.

  dbg('keyauth emulation ACTIVE — overrides installed');
})();


